module pwm_dimmer (
    input wire clk,
    input wire rst,
    input wire ce,
    input wire [7:0] duty_in,
    output wire pwm_out
);
    reg [7:0] cnt      = 8'd0;   // free-running ramp
    reg [7:0] duty_reg = 8'd0;   // duty latched at period start
    reg [7:0] high_cnt = 8'd0;   // high-time accumulated this period
    reg       high_pend = 1'b0;  // compare result retimed out of the accumulator adder path

    always @(posedge clk)
        if (rst) begin
            cnt      <= 8'd0;
            duty_reg <= 8'd0;
            high_cnt <= 8'd0;
            high_pend <= 1'b0;
        end else if (ce) begin
            if (cnt == 8'd0) begin
                duty_reg <= duty_in;
                high_cnt  <= 8'd0;
                high_pend <= (duty_in != 8'd0);
                cnt      <= 8'd1;
            end else if (cnt == 8'hFF) begin
                cnt      <= 8'd0;
                high_cnt <= 8'd0;
                high_pend <= 1'b0;
            end else begin
                cnt      <= cnt + 8'd1;
                high_cnt  <= high_cnt + (high_pend ? 8'd1 : 8'd0);
                high_pend <= (cnt < duty_reg);
            end
        end

    assign pwm_out = (cnt < duty_reg);

    always @(posedge clk)
        if (pwm_out)
            assert (high_cnt < duty_reg);
endmodule

module pwm_dimmer (
    input wire clk,
    input wire rst,
    input wire ce,
    input wire [7:0] duty_in,
    output wire pwm_out
);
    reg [7:0] cnt      = 8'd0;   // free-running ramp
    reg [7:0] duty_reg = 8'd0;   // duty latched at period start
    reg [7:0] high_cnt = 8'd0;   // high-time accumulated this period

    always @(posedge clk)
        if (rst) begin
            cnt      <= 8'd0;
            duty_reg <= 8'd0;
            high_cnt <= 8'd0;
        end else if (ce) begin
            if (cnt == 8'd0) begin
                duty_reg <= duty_in;
                high_cnt <= (duty_in != 8'd0) ? 8'd1 : 8'd0;
                cnt      <= 8'd1;
            end else if (cnt == 8'hFF) begin
                cnt      <= 8'd0;
                high_cnt <= 8'd0;
            end else begin
                cnt      <= cnt + 8'd1;
                high_cnt <= high_cnt + ((cnt < duty_reg) ? 8'd1 : 8'd0);
            end
        end

    assign pwm_out = (cnt < duty_reg);

    always @(posedge clk)
        if (pwm_out)
            assert (high_cnt < duty_reg);

   // Duty accounting check: once the pulse for this period has ended,
   // the accumulated high time must equal the programmed duty exactly,
   // otherwise the average brightness would drift from the setpoint.
   always @(posedge clk)
       if (!pwm_out)
           assert (high_cnt == duty_reg);
endmodule

