module stack_hwm (
    input wire clk,
    input wire rst,
    input wire ce,
    input wire push,
    input wire pop,
    input wire [7:0] din,
    output wire [7:0] top
);
    reg [3:0] sp;
    reg [3:0] hwm;
    reg [7:0] mem [0:15];
    reg        wb_v;
    reg [7:0]  wb_d;
    initial begin sp = 4'd0; hwm = 4'd0; wb_v = 1'b0; wb_d = 8'h00; end

    wire [3:0] occ = sp + {3'b000, wb_v};
    wire do_push = ce && push && (occ != 4'd8);
    wire do_pop  = ce && pop  && (occ != 4'd0);
    wire [3:0] nxt = occ + 4'd1;

    assign top = wb_v ? wb_d : ((sp == 4'd0) ? 8'h00 : mem[sp - 4'd1]);

    always @(posedge clk) begin
        if (rst) begin
            sp  <= 4'd0;
            hwm <= 4'd0;
            wb_v <= 1'b0;
            wb_d <= 8'h00;
        end else begin
            case ({do_push, do_pop})
                2'b10: begin
                    if (wb_v) begin
                        mem[sp] <= wb_d;
                        sp <= sp + 4'd1;
                    end
                    wb_v <= 1'b1;
                    wb_d <= din;
                    if (nxt > hwm) hwm <= nxt;
                end
                2'b01: begin
                    if (wb_v) wb_v <= 1'b0;
                    else      sp   <= sp - 4'd1;
                end
                default: if (ce && wb_v) begin
                    mem[sp] <= wb_d;
                    sp      <= sp + 4'd1;
                    wb_v    <= 1'b0;
                end
            endcase
        end
    end

    always @(posedge clk)
        if (sp == 4'd8)
            assert (hwm == 4'd8);
endmodule

