module watchdog (
    input wire clk,
    input wire rst,
    input wire i_ce,
    input wire kick,
    input wire ack,
    output reg fault
);
    reg [3:0] timer;
    reg [3:0] elapsed;
    initial begin timer = 4'd8; elapsed = 4'd0; fault = 1'b0; end

    always @(posedge clk) begin
        if (rst) begin
            timer   <= 4'd8;
            elapsed <= 4'd0;
            fault   <= 1'b0;
        end else if (i_ce) begin
            if (ack) begin
                timer   <= 4'd8;
                elapsed <= 4'd0;
                fault   <= 1'b0;
            end else if (kick && !fault) begin
                timer   <= 4'd8;
                elapsed <= 4'd0;
            end else begin
                if (timer != 4'd0)   timer   <= timer - 4'd1;
                if (elapsed != 4'd8) elapsed <= elapsed + 4'd1;
                if (timer == 4'd1)   fault   <= 1'b1;
            end
        end
    end

    always @(posedge clk)
        if (elapsed == 4'd8)
            assert (fault);
endmodule

