module pwm_dimmer (
    input wire clk,
    input wire rst,
    input wire ce,
    input wire [7:0] duty_in,
    output wire pwm_out
);
    reg [7:0] cnt      = 8'd0;   // free-running ramp
    reg [7:0] duty_reg = 8'd0;   // duty latched at period start
    reg [7:0] high_cnt = 8'd0;   // high-time accumulated this period

   // compare -> accumulate path registered four deep to meet timing at the
   // top clock rate; each stage carries one pending high-time increment and
   // the last stage is the PWM output itself, so output and accumulator stay
   // aligned by construction.
   reg inc_s0 = 1'b0;
   reg inc_s1 = 1'b0;
   reg inc_s2 = 1'b0;
   reg inc_s3 = 1'b0;

    always @(posedge clk)
        if (rst) begin
            cnt      <= 8'd0;
            duty_reg <= 8'd0;
            high_cnt <= 8'd0;
           inc_s0   <= 1'b0;
           inc_s1   <= 1'b0;
           inc_s2   <= 1'b0;
           inc_s3   <= 1'b0;
        end else if (ce) begin
            if (cnt == 8'd0) begin
                duty_reg <= duty_in;
               high_cnt <= 8'd0;
               inc_s0   <= (duty_in != 8'd0);
               inc_s1   <= inc_s0;
               inc_s2   <= inc_s1;
               inc_s3   <= inc_s2;
                cnt      <= 8'd1;
            end else if (cnt == 8'hFF) begin
                cnt      <= 8'd0;
                high_cnt <= 8'd0;
               inc_s0   <= 1'b0;
               inc_s1   <= 1'b0;
               inc_s2   <= 1'b0;
               inc_s3   <= 1'b0;
            end else begin
                cnt      <= cnt + 8'd1;
               high_cnt <= high_cnt + (inc_s3 ? 8'd1 : 8'd0);
               inc_s0   <= (cnt < duty_reg);
               inc_s1   <= inc_s0;
               inc_s2   <= inc_s1;
               inc_s3   <= inc_s2;
            end
        end

   assign pwm_out = inc_s3;

    always @(posedge clk)
        if (pwm_out)
            assert (high_cnt < duty_reg);
endmodule

