    // support.
    wire [2:0] grant = (remaining < {1'b0, tokens}) ? remaining[2:0] : tokens;

    always @(posedge clk) begin
        if (rst) begin
            pending <= 3'd0;
            hold    <= 8'h00;
        end else if (load) begin
            pending <= grant;
            hold    <= src_data;
        end else if (beat) begin
            pending <= pending - 3'd1;
        end
    end

    token_bucket u_bucket (
        .clk       (clk),
        .rst       (rst),
        .drip      (drip),
        .spend     (beat),
        .tokens    (tokens),
        .tokens_hi (tokens_hi)
    );

    dma_copier u_dma (
        .clk       (clk),
        .rst       (rst),
        .ce        (beat),
        .rd_data   (hold),
        .wr_addr   (wr_addr),
        .remaining (remaining),
        .wr_data   (wr_data),
        .done      (done)
    );

    // Composed property: any beat still sitting in the burst queue must have
    // somewhere left to land in the destination block.
    always @(posedge clk)
        if (pending != 3'd0)
            assert (remaining != 4'd0);
endmodule

