module stack_xor (
    input wire clk,
    input wire rst,
    input wire push,
    input wire pop,
    input wire [3:0] data,
    output reg [2:0] sp,
    output reg [3:0] xor_acc
);
    reg [3:0] m0, m1, m2, m3;
    reg [2:0] sp_b;
    initial begin sp = 0; xor_acc = 0; m0 = 0; m1 = 0; m2 = 0; m3 = 0; sp_b = 0; end

    wire [3:0] used = {1'b0, sp} + {1'b0, sp_b};
    wire do_push = push && !pop && (used != 4'd4);
    wire do_pop  = pop  && !push && (sp != 3'd0);
    wire do_a2b  = push && pop && (sp != 3'd0);
    wire do_b2a  = push && pop && (sp == 3'd0) && (sp_b != 3'd0);
    wire [3:0] top = (sp == 3'd1) ? m0 : (sp == 3'd2) ? m1 : (sp == 3'd3) ? m2 : m3;
    wire [3:0] b_top = (sp_b == 3'd1) ? m3 : (sp_b == 3'd2) ? m2 : (sp_b == 3'd3) ? m1 : m0;

    always @(posedge clk) begin
        if (rst) begin
            sp <= 3'd0;
            sp_b <= 3'd0;
            xor_acc <= 4'd0;
        end else if (do_push) begin
            case (sp)
                3'd0:    m0 <= data;
                3'd1:    m1 <= data;
                3'd2:    m2 <= data;
                default: m3 <= data;
            endcase
            sp <= sp + 3'd1;
            xor_acc <= xor_acc ^ data;
        end else if (do_pop) begin
            sp <= sp - 3'd1;
            xor_acc <= xor_acc ^ top;
        end else if (do_a2b) begin
            case (sp_b)
                3'd0:    m3 <= top;
                3'd1:    m2 <= top;
                3'd2:    m1 <= top;
                default: m0 <= top;
            endcase
            sp   <= sp - 3'd1;
            sp_b <= sp_b + 3'd1;
            xor_acc <= xor_acc ^ top;
        end else if (do_b2a) begin
            m0 <= b_top;
            sp <= 3'd1;
            sp_b <= sp_b - 3'd1;
            xor_acc <= xor_acc ^ b_top;
        end
    end

    always @(posedge clk)
        if (sp == 3'd0)
            assert (xor_acc == 4'd0);
endmodule

