    dma_copier u_dma (
        .clk       (clk),
        .rst       (rst),
       .ce        (commit),
       .rd_data   (wbeat_d),
        .wr_addr   (wr_addr),
        .remaining (remaining),
        .wr_data   (wr_data),
        .done      (done)
