module gray_cdc_counter (
    input  wire       clk,
    input  wire       rst,
    input  wire       step,
    output reg  [3:0] gray
);
    // shadow binary counter
    reg [3:0] bin;
    // previous emitted gray value, and a sticky flag saying one step happened
    reg [3:0] gray_prev;
    reg       changed;
    // running parity of the emitted gray word, kept incrementally
    reg       par;

    initial bin       = 4'd0;
    initial gray      = 4'b0000;
    initial gray_prev = 4'b0000;
    initial changed   = 1'b0;
    initial par       = 1'b0;

    wire [3:0] bin_nxt  = bin + 4'd1;
    // Gray increment performed on the gray word itself: with an even number
    // of ones toggle bit 0, otherwise toggle the bit left of the rightmost
    // one (wrapping onto the MSB at the end of the sequence). par supplies
    // the ones-parity so it never has to be recomputed from gray.
    wire [3:0] gray_lsb1 = gray & (~gray + 4'd1);
    wire [3:0] gray_shl  = {gray_lsb1[2:0], 1'b0};
    wire [3:0] gray_tog  = par ? ((gray_shl == 4'b0000) ? 4'b1000 : gray_shl)
                               : 4'b0001;
    wire [3:0] gray_nxt  = gray ^ gray_tog;

    always @(posedge clk) begin
        if (rst) begin
            bin       <= 4'd0;
            gray      <= 4'b0000;
            gray_prev <= 4'b0000;
            changed   <= 1'b0;
            par       <= 1'b0;
        end else if (step) begin
            bin       <= bin_nxt;
            gray      <= gray_nxt;
            gray_prev <= gray;
            changed   <= 1'b1;
            par       <= ~par;
        end
    end

    // P: once a step has been taken, the current and previous gray words
    //    differ in exactly one bit (safe for clock-domain crossing).
    wire [3:0] diff = gray ^ gray_prev;

    always @(posedge clk) begin
        if (changed)
            assert ((diff != 4'b0000) && ((diff & (diff - 4'd1)) == 4'b0000));
    end

    // Q: the top gray bit tracks the top binary bit, so it can be used as a
    //    half-full flag without decoding the gray word.
    always @(posedge clk)
        assert (gray[3] == bin[3]);
endmodule

