module token_bucket (
    input wire clk,
    input wire rst,
    input wire drip,
    input wire spend,
    output reg [2:0] tokens,
    output reg tokens_hi
);
    reg deep;  // registered level>=3 flag, re-evaluated when the level moves
   // reserve slot: drips that arrive while the bucket is already deep park here
   reg [1:0] resv;
   wire [2:0] level = tokens + {1'b0, resv};
   wire drip_en  = drip  && (level != 3'd4);
    wire spend_en = spend && (tokens != 3'd0);
    wire inc = drip_en && !spend_en;
    wire dec = spend_en && !drip_en;

   // a deep bucket diverts fresh drips into the reserve instead of raising the level
   wire park = inc && deep && (resv != 2'd2);
   wire fill = inc && !park;
   // burst drain: while the bucket is deep a spend sheds two tokens at once; the
   // second one is taken from the reserve whenever the reserve is holding something
   wire bulk  = dec && deep && (resv == 2'd0);
   wire drain = dec && deep && (resv != 2'd0);
   wire lite  = dec && !bulk;
   // the reserve folds back into the bucket once the level is no longer deep
   wire refill = !inc && !dec && !deep && (resv != 2'd0);
   wire [2:0] nxt = fill   ? tokens + 3'd1 :
                    bulk   ? tokens - 3'd2 :
                    lite   ? tokens - 3'd1 :
                    refill ? tokens + 3'd1 : tokens;
   wire [1:0] nxt_resv = park               ? resv + 2'd1 :
                         (drain || refill)  ? resv - 2'd1 : resv;
   wire [2:0] nxt_level = nxt + {1'b0, nxt_resv};

    initial tokens   = 3'd0;
    initial tokens_hi = 1'b0;
    initial deep = 1'b0;
   initial resv = 2'd0;

    always @(posedge clk) begin
        if (rst) begin
            tokens    <= 3'd0;
            tokens_hi <= 1'b0;
            deep      <= 1'b0;
           resv      <= 2'd0;
        end else begin
            tokens <= nxt;
           resv   <= nxt_resv;
           if (inc || dec) deep <= (nxt_level >= 3'd3);

           if (fill && tokens == 3'd1)        tokens_hi <= 1'b1;
           else if (refill && tokens == 3'd1) tokens_hi <= 1'b1;
            else if (lite && tokens == 3'd2) tokens_hi <= 1'b0;
            else if (bulk && tokens == 3'd3) tokens_hi <= 1'b0;
        end
    end

    always @(posedge clk)
        if (tokens_hi) assert (tokens != 3'd0);
endmodule

