module dma_copier (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    output reg  [3:0] remaining,
    output reg  [3:0] sent,
    output reg        busy,
    output reg        done
);
    // the bus grants at most five words per burst, so an 8-word block is
    // issued as a 5-word burst plus a deferred 3-word tail
    reg  [3:0] pending;
    // block length is fixed at 8 words
    initial remaining = 4'd5;
    initial pending   = 4'd3;
    initial sent      = 4'd0;
    initial busy      = 1'b1;
    initial done      = 1'b0;

    always @(posedge clk) begin
        if (rst) begin
            remaining <= 4'd5;
            pending   <= 4'd3;
            sent      <= 4'd0;
            busy      <= 1'b1;
            done      <= 1'b0;
        end else if (ce) begin
            if (remaining != 4'd0) begin
                remaining <= remaining - 4'd1;
                sent      <= sent + 4'd1;
                if (remaining == 4'd1 && pending == 4'd0)
                    busy <= 1'b0;
            end
            else if (pending != 4'd0) begin
                // burst boundary: re-arm the engine for the deferred tail
                remaining <= pending;
                pending   <= 4'd0;
                busy      <= 1'b1;
            end
            // done is raised the cycle after the last word retires
            done <= (remaining == 4'd0 && pending == 4'd0);
        end
    end

    // P: the engine must never report completion while still claiming to copy
    always @(posedge clk)
        if (done)
            assert (!busy);
endmodule

