module lfsr_shadow_capture (
    input  wire       i_clk,
    input  wire       i_rst,
    input  wire       i_ce,
    input  wire       i_cap,
    output wire [7:0] o_rand,
    output wire [7:0] o_shadow,
    output wire       o_shadow_valid
);
    // maximal-length 8-bit LFSR, taps at 8,6,5,4 (x^8 + x^6 + x^5 + x^4 + 1)
    reg [7:0] lfsr;
   reg [7:0] lfsr_b;
    reg [7:0] shadow;
    reg       shadow_valid;
   reg [1:0] ch_en;   // capture mixer channel enables: bit0 = gen A, bit1 = gen B
  reg [7:0] cap_data;  // capture pipeline stage: sampled word awaiting commit
  reg       cap_pend;  // stage holds a word not yet written to the shadow

    initial lfsr         = 8'h01;
   initial lfsr_b       = 8'hA5;
    initial shadow       = 8'h00;
    initial shadow_valid = 1'b0;
   initial ch_en        = 2'b01;
  initial cap_data     = 8'h00;
  initial cap_pend     = 1'b0;

    wire fb = lfsr[7] ^ lfsr[5] ^ lfsr[4] ^ lfsr[3];
   wire fb_b = lfsr_b[7] ^ lfsr_b[5] ^ lfsr_b[4] ^ lfsr_b[3];
   // shared capture port: XOR of whichever generator channels are enabled
   wire [7:0] sample = (ch_en[0] ? lfsr : 8'h00) ^ (ch_en[1] ? lfsr_b : 8'h00);
  // two-cycle capture: register the shared port, then commit it into the shadow
  wire cap_start  = i_ce && i_cap && !cap_pend;   // stall a request while one is in flight
  wire cap_commit = i_ce && cap_pend;
  // generators hold on the sample cycle so the staged word matches the reported channel
  wire gen_adv    = i_ce && !cap_start;

    always @(posedge i_clk) begin
        if (i_rst) begin
            lfsr <= 8'h01;
           lfsr_b <= 8'hA5;
       end else if (gen_adv) begin
            lfsr <= { lfsr[6:0], fb };
           lfsr_b <= { lfsr_b[6:0], fb_b };
        end
    end

   // capture stage: the shared port is registered before it reaches the shadow
   always @(posedge i_clk) begin
       if (i_rst) begin
           cap_data <= 8'h00;
           cap_pend <= 1'b0;
       end else if (cap_start) begin
           cap_data <= sample;
           cap_pend <= 1'b1;
       end else if (cap_commit) begin
           cap_pend <= 1'b0;
       end
   end

    // shadow register: snapshots the generator output on request
    always @(posedge i_clk) begin
        if (i_rst) begin
            shadow       <= 8'h00;
            shadow_valid <= 1'b0;
           ch_en        <= 2'b01;
       end else if (cap_commit) begin
          shadow       <= cap_data;
            shadow_valid <= 1'b1;
