    initial nmatch = 4'd0;

   // match accounting is pipelined one cycle behind the character counter
   reg m_stage;
   initial m_stage = 1'b0;

    // scan a fixed 8-character string, counting occurrences of the target char
    assign done = (nchars == 4'd8);

    always @(posedge clk) begin
        if (rst) begin
            nchars <= 4'd0;
            nmatch <= 4'd0;
