    always @(posedge clk) begin
        if (rst) begin
            timer   <= 4'd8;
            elapsed <= 4'd0;
            fault   <= 1'b0;
period  <= 4'd8;
            resv    <= 4'd0;
        end else if (i_ce) begin
            if (ack) begin
timer   <= period_tight - GRACE;
resv    <= GRACE;
period  <= period_tight;
                elapsed <= 4'd0;
                fault   <= 1'b0;
            end else if (kick && !fault) begin
timer   <= period_relax - GRACE;
resv    <= GRACE;
period  <= period_relax;
                elapsed <= 4'd0;
