module token_bucket (
    input  wire clk,
    input  wire rst,
    input  wire ce,
    input  wire req,
    input  wire drip,
    output wire grant
);
    reg [3:0] tokens = 4'd8;   // tokens currently in the bucket
    reg [3:0] free   = 4'd0;   // room left in the bucket (shadow accounting)
    reg [3:0] cap    = 4'd8;   // current burst allowance (adaptive capacity)
   // secondary lane: overflow bucket drawing on the same allowance pool
   reg [3:0] tokens_b = 4'd4;
   reg [3:0] free_b   = 4'd0;
   reg [3:0] cap_b    = 4'd4;

    wire spend   = ce && req  && (tokens != 4'd0);
    wire refill  = ce && drip && (free   != 4'd0);
   // the secondary lane serves a request only when the primary bucket is
   // dry, and absorbs a drip only when the primary bucket has no room left
   wire spend_b  = ce && req  && (tokens == 4'd0) && (tokens_b != 4'd0);
   wire refill_b = ce && drip && (free   == 4'd0) && (free_b   != 4'd0);
   // starved: a request found the bucket empty, so pull one slot of
   // allowance across from the secondary lane; that lane may only give a
   // slot up above its own reserve, and only out of room it is not using
   wire restore = ce && req && (tokens == 4'd0) && (cap_b != 4'd4) && (free_b != 4'd0);
    // fully idle with room going unused: retire one slot of allowance
    wire reclaim = ce && !req && !drip && (free != 4'd0) && (cap != 4'd4);

   assign grant = spend || spend_b;

    always @(posedge clk) begin
        if (rst) begin
            tokens <= 4'd8;
            free   <= 4'd0;
            cap    <= 4'd8;
           tokens_b <= 4'd4;
           free_b   <= 4'd0;
           cap_b    <= 4'd4;
        end else begin
            tokens <= tokens - spend + refill;
            free   <= free   + spend - refill + restore - reclaim;
            cap    <= cap    + restore - reclaim;
           tokens_b <= tokens_b - spend_b + refill_b;
           free_b   <= free_b   + spend_b - refill_b - restore + reclaim;
           cap_b    <= cap_b    - restore + reclaim;
        end
    end

    // P: if the bucket is not completely full, at least one slot's worth of
    // tokens is missing, so occupancy cannot exceed CAP-1.
    always @(posedge clk)
        if (free != 4'd0)
            assert (tokens <= 4'd7);
endmodule

