module substr_search (
    input wire clk,
    input wire rst,
    input wire ce,
    input wire [7:0] in_char,
    output reg [1:0] idx,
    output reg found
);
    localparam [7:0] TGT = 8'h61; // 'a'
    localparam [7:0] DELIM = 8'h20; // ' '

    // engine B: delimited-word matcher for "aa", sharing engine A's counter
    reg wpend; // engine B result awaiting commit onto the shared found flag
    reg hold;  // shared index frozen while a match position is being reported


    initial idx   = 2'd0;
    initial found = 1'b0;
    initial wpend = 1'b0;
    initial hold  = 1'b0;

    // matches the 3-character run "aaa"; freezes once idx saturates at 3
    always @(posedge clk) begin
        if (rst) begin
            idx   <= 2'd0;
            found <= 1'b0;
            wpend <= 1'b0;
            hold  <= 1'b0;
        end else if (ce) begin
            // commit stage: engine B publishes onto the shared found flag
            if (wpend) begin
                wpend <= 1'b0;
                found <= 1'b1;
            end
            if (!hold && idx != 2'd3) begin
            if (in_char == TGT) begin
                idx <= idx + 2'd1;
                if (idx == 2'd2)
                    found <= 1'b1;
            end else if (in_char == DELIM && idx == 2'd2) begin
                // "aa" closed by a delimiter: freeze the shared index at the
                // match length and hand the result to the commit stage
                wpend <= 1'b1;
                hold  <= 1'b1;
            end else begin
                idx <= 2'd0;
            end
            end
        end
    end

    // P: the found flag implies a non-empty partial match is held
    always @(posedge clk)
        if (found) assert (idx != 2'd0);
endmodule

