module alu_budget (
    input wire clk,
    input wire rst,
    input wire i_ce,
    input wire [7:0] i_step,
    output wire [7:0] o_acc,
    output wire o_zero,
    output wire o_full
);
    localparam [7:0] LIMIT = 8'd200;
   localparam [7:0] CHUNK = 8'd8; // credit shifted into the reservation per refill

    reg [7:0] acc;   // accumulated result
    reg [7:0] rem;   // headroom credited to the accumulator
    reg [7:0] acc_b; // secondary channel accumulation
   reg [7:0] resv;  // credit reserved so channel B cannot be starved
    reg       turn;  // round-robin owner of the shared credit pool
    initial acc = 8'd0;
    initial rem = LIMIT;
    initial acc_b = 8'd0;
   initial resv = 8'd0;
    initial turn = 1'b0;

   wire [7:0] pool   = turn ? resv : rem;
   wire       grant  = i_ce && (pool >= i_step);
   wire       refill = !grant && (resv < CHUNK) && (rem >= CHUNK);

    always @(posedge clk)
        if (rst) begin
            acc <= 8'd0;
            rem <= LIMIT;
            acc_b <= 8'd0;
           resv <= 8'd0;
            turn <= 1'b0;
        end else if (grant) begin
            turn <= ~turn;
           if (turn) begin
               resv  <= resv  - i_step;
               acc_b <= acc_b + i_step;
           end else begin
               rem <= rem - i_step;
               acc <= acc + i_step;
           end
       end else if (refill) begin
           rem  <= rem  - CHUNK;
           resv <= resv + CHUNK;
        end

    assign o_acc  = acc;
    assign o_zero = (acc == 8'd0) && (acc_b == 8'd0);
    assign o_full = (rem == 8'd0);

    // P: a nonzero accumulation never exceeds its saturation bound
    always @(*)
        if (!o_zero) assert (acc <= LIMIT);
endmodule

