module dma_copier (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    input  wire [7:0] rd_data,
    output reg  [3:0] wr_addr,
    output reg  [3:0] remaining,
    output reg  [7:0] wr_data,
    output wire       done
);
    localparam [3:0] TOTAL = 4'd8;

    initial wr_addr   = 4'd0;
    initial remaining = TOTAL;
    initial wr_data   = 8'h00;

   // Running XOR checksum of the block. The last beat of the transfer
   // writes the checksum byte instead of the raw source byte, so the
   // destination block is self-checking.
   reg [7:0] csum;
   initial csum = 8'h00;

    assign done = (remaining == 4'd0);

    always @(posedge clk) begin
        if (rst) begin
            wr_addr   <= 4'd0;
            remaining <= TOTAL;
            wr_data   <= 8'h00;
           csum      <= 8'h00;
        end else if (ce && remaining != 4'd0) begin
            wr_addr   <= wr_addr + 4'd1;
            remaining <= remaining - 4'd1;
           csum      <= csum ^ rd_data;
           wr_data   <= (remaining == 4'd1) ? (csum ^ rd_data) : rd_data;
        end
    end

    // P: while the block copy is still in flight, the write pointer must stay
    // inside the destination block (0..7).
    always @(posedge clk)
        if (!done)
            assert (wr_addr <= 4'd7);

   // P2: once the block copy has finished, the write pointer must have
   // advanced exactly past the last byte of the destination block.
   always @(posedge clk)
       if (done)
           assert (wr_addr == TOTAL);
endmodule

