module minmax_abs_track (
    input wire i_clk,
    input wire i_rst,
    input wire i_ce,
    input wire i_push,
    input wire signed [7:0] i_val,
    output wire [7:0] o_min,
    output wire [7:0] o_max,
    output wire [3:0] o_count,
    output wire o_bad
);
    // Tracks the running min and max of the magnitudes (absolute values) of a
    // stream of signed samples, plus a saturating sample counter and a latched
    // order-violation flag.

    reg [7:0] mn;
    reg [7:0] mx;
    reg       valid;
    reg [3:0] count;
    reg       bad;
    // programmable squelch floor (noise gate threshold)
    reg [7:0] flr;

    initial mn    = 8'hff;
    initial mx    = 8'h00;
    initial valid = 1'b0;
    initial count = 4'd0;
    initial bad   = 1'b0;
    initial flr   = 8'h00;

    // unsigned magnitude of the signed input (|-128| == 8'h80 fits unsigned)
    wire [7:0] mag = i_val[7] ? (~i_val + 8'd1) : i_val;

    // floor code shares the data bus with the samples
    wire [7:0] fcode = i_val;
    // squelch: a sample quieter than the floor is reported as the floor
    wire [7:0] gated = (mag < flr) ? flr : mag;

    always @(posedge i_clk) begin
        if (i_rst) begin
            mn    <= 8'hff;
            mx    <= 8'h00;
            valid <= 1'b0;
            count <= 4'd0;
            bad   <= 1'b0;
            flr   <= 8'h00;
        end else if (i_ce) begin
            // order checker: samples the registered extremes, gated by the
            // *counter* rather than by the valid flag
            bad <= (count != 4'd0) && (mn > mx);

            // floor programming: an enabled cycle without a push carries a
            // new floor code.  A code above the recorded peak would strand
            // that peak underneath the floor, so it is refused while a
            // window is open.
            if (!i_push && (!valid || (fcode <= mx)))
                flr <= fcode;

            // the recorded minimum saturates at the floor: a minimum taken
            // before the floor was raised is no longer a legal reading
            if (mn < flr)
                mn <= flr;

            if (i_push) begin
                if (!valid) begin
                    mn <= gated;
                    mx <= gated;
                end else begin
                    if (gated < mn)
                        mn <= gated;
                    if (gated > mx)
                        mx <= gated;
                end
                valid <= 1'b1;
                count <= (count == 4'd15) ? 4'd15 : (count + 4'd1);
            end
        end
    end

    assign o_min   = mn;
    assign o_max   = mx;
    assign o_count = count;
    assign o_bad   = bad;

    // Property: once at least one sample has been absorbed, the order checker
    // must never have fired.
    always @(posedge i_clk)
        if (valid)
            assert (!bad);

endmodule

