module vend_credit (
    input wire clk,
    input wire i_reset,
    input wire i_ce,
    input wire i_dime,
    output wire o_dispense,
    output wire [5:0] o_change
);
    reg [3:0] units = 0;      // credit in 5-cent units
    reg [5:0] cents = 0;      // credit in cents
    reg       dispense = 0;
    reg [5:0] change = 0;
    reg [5:0] chg_stage = 0;   // vend total waiting on the change subtractor
    reg       vend_stage = 0;  // a vend was deducted from credit last cycle

    wire [3:0] inc_u = i_dime ? 4'd2  : 4'd1;
    wire [5:0] inc_c = i_dime ? 6'd10 : 6'd5;
    wire [3:0] nu = units + inc_u;
    wire [5:0] nc = cents + inc_c;

    always @(posedge clk)
        if (i_reset) begin
            units    <= 4'd0;
            cents    <= 6'd0;
            dispense <= 1'b0;
            change   <= 6'd0;
            chg_stage  <= 6'd0;
            vend_stage <= 1'b0;
        end else if (i_ce) begin
            // stage 2: finish the change subtraction started last cycle
            dispense <= vend_stage;
            if (vend_stage) change <= chg_stage - 6'd25;
