            if (nu >= 4'd5) begin
                units    <= nu - 4'd5;
                cents    <= nc - 6'd25;
                chg_stage  <= nc;
                vend_stage <= 1'b1;
            end else begin
                units    <= nu;
                cents    <= nc;
                vend_stage <= 1'b0;
            end
        end

    assign o_dispense = dispense;
    assign o_change   = change;

    always @(posedge clk)
        if (dispense) assert (change <= 6'd5);
endmodule

