module chess_clock (
    input  wire       clk,
    input  wire       rst,
    input  wire       tick,   // enable: when low, all state is held
    input  wire       press,  // toggles which side is running
    output reg  [5:0] w_time,
    output reg  [5:0] b_time,
    output reg  [5:0] elapsed,
    output reg        turn
);
    localparam [5:0] BUDGET = 6'd16;

    // clock is frozen once either side has run out
    wire frozen = (w_time == 6'd0) || (b_time == 6'd0);

    // press is level-sampled at ticks: only a fresh press (a rising edge
    // between two ticks) hands the clock over, so holding the button down
    // does not flip the running side on every tick
    reg  press_q;
    wire press_edge = press && !press_q;

    initial w_time  = BUDGET;
    initial b_time  = BUDGET;
    initial elapsed = 6'd0;
    initial turn    = 1'b0;
    initial press_q = 1'b0;

    always @(posedge clk) begin
        if (rst) begin
            w_time  <= BUDGET;
            b_time  <= BUDGET;
            elapsed <= 6'd0;
            turn    <= 1'b0;
            press_q <= 1'b0;
        end else if (tick && !frozen) begin
            if (turn == 1'b0)
                w_time <= w_time - 6'd1;
            else
                b_time <= b_time - 6'd1;

            elapsed <= elapsed + 6'd1;

            if (press_edge)
                turn <= ~turn;

            press_q <= press;
        end
    end

    // P: while the clock is still running, at most BUDGET*2-2 ticks can have elapsed
    always @(posedge clk)
        if (!frozen)
            assert (elapsed <= 6'd30);

    // Q: the clock cannot have run out before one full budget was burned
    always @(posedge clk)
        if (frozen)
            assert (elapsed >= 6'd16);
endmodule

