module nano_alu_flags (
    input wire clk,
    input wire rst,
    input wire ce,
    input wire [1:0] op,      // 00=ADD 01=SUB 10=AND 11=PASS/refresh
    input wire [7:0] b,
    output reg [7:0] acc,
    output reg zf,            // zero flag
    output reg nf,            // negative (sign) flag
    output reg cf             // carry flag
);

   // accumulator writeback is pipelined one enabled cycle: the ALU result
   // waits in the writeback stage before it is retired into acc
   reg [7:0] stage;
   reg       stage_v;

    initial begin
        acc = 8'h00;
        zf  = 1'b1;           // acc == 0 at start
        nf  = 1'b0;
        cf  = 1'b0;
       stage   = 8'h00;
       stage_v = 1'b0;
    end

   // bypass the pending writeback so ops never read a stale acc
   wire [7:0] a_cur = stage_v ? stage : acc;

   wire [8:0] add_res = {1'b0, a_cur} + {1'b0, b};
   wire [8:0] sub_res = {1'b0, a_cur} - {1'b0, b};
   wire [7:0] and_res = a_cur & b;

    reg [7:0] res;
    reg        carry;

    always @(*) begin
        case (op)
            2'b00: begin res = add_res[7:0]; carry = add_res[8]; end
            2'b01: begin res = sub_res[7:0]; carry = sub_res[8]; end
            2'b10: begin res = and_res;      carry = 1'b0;       end
           default: begin res = a_cur;      carry = cf;         end // PASS
        endcase
    end

    always @(posedge clk) begin
        if (rst) begin
            acc <= 8'h00;
            zf  <= 1'b1;
            nf  <= 1'b0;
            cf  <= 1'b0;
           stage   <= 8'h00;
           stage_v <= 1'b0;
        end else if (ce) begin
           if (stage_v)
               acc <= stage;              // retire the pending writeback
           stage   <= res;
           stage_v <= (op != 2'b11);      // PASS refresh adds no new write
            zf  <= (res == 8'h00);
            cf  <= carry;
            // sign flag is only rewritten by ops that actually change acc
            if (op != 2'b11)
                nf <= res[7];
        end
    end

    // P: the zero flag and the negative flag are never both asserted
    always @(posedge clk)
        if (zf)
            assert (!nf);

endmodule

