    wire       c_valid = |req;
    wire [2:0] c_index = req[7] ? 3'd7 :
                         req[6] ? 3'd6 :
                         req[5] ? 3'd5 :
                         req[4] ? 3'd4 :
                         req[3] ? 3'd3 :
                         req[2] ? 3'd2 :
                         req[1] ? 3'd1 : 3'd0;

   // secondary grant: the highest priority request strictly below the primary
   // one, so one capture can produce two grants
   wire [7:0] req2     = req & ~(8'h01 << c_index);
   wire       c2_valid = |req2;
   wire [2:0] c2_index = req2[7] ? 3'd7 :
                         req2[6] ? 3'd6 :
                         req2[5] ? 3'd5 :
                         req2[4] ? 3'd4 :
                         req2[3] ? 3'd3 :
                         req2[2] ? 3'd2 :
                         req2[1] ? 3'd1 : 3'd0;

    // stage 1: captured request vector plus its encoding
    reg [7:0] q_req;
    reg       q_valid;
    reg [2:0] q_index;
   reg       q2_valid;
   reg [2:0] q2_index;
   // the output stage is a single shared port: alternate which grant slot
   // drains through it each beat
   reg       sel;

    initial begin
        q_req   = 8'h00;
        q_valid = 1'b0;
        q_index = 3'd0;
       q2_valid = 1'b0;
       q2_index = 3'd0;
       sel      = 1'b0;
        y_valid = 1'b0;
        y_index = 3'd0;
        y_bit   = 1'b0;
    end

    always @(posedge clk) begin
        if (rst) begin
            q_req   <= 8'h00;
            q_valid <= 1'b0;
            q_index <= 3'd0;
           q2_valid <= 1'b0;
           q2_index <= 3'd0;
           sel      <= 1'b0;
        end else if (i_ce) begin
            q_req   <= req;
            q_valid <= c_valid;
            q_index <= c_index;
