module pwm_dimmer (
    input wire clk,
    input wire rst,
    input wire ce,
    input wire [7:0] duty_in,
    output wire pwm_out
);
    reg [7:0] cnt      = 8'd0;   // free-running ramp
    reg [7:0] duty_reg = 8'd0;   // duty latched at period start
    reg [7:0] high_cnt = 8'd0;   // high-time accumulated this period
    reg [3:0] hi_pend  = 4'd0;   // high cycles waiting to be folded into the accumulator
    reg       hi_q     = 1'b0;   // compare result, registered ahead of the accumulator
    reg [7:0] duty_cap = 8'd0;   // duty request captured at ramp end, after foldback clamp

    localparam [7:0] HI_LIMIT = 8'd192; // high cycles per period allowed by thermal budget

    always @(posedge clk)
        if (rst) begin
            cnt      <= 8'd0;
            duty_reg <= 8'd0;
            high_cnt <= 8'd0;
            hi_pend  <= 4'd0;
            hi_q     <= 1'b0;
            duty_cap <= 8'd0;
        end else if (ce) begin
            if (cnt == 8'd0) begin
                duty_reg <= duty_cap;
                high_cnt <= 8'd0;
                hi_pend  <= 4'd0;
                hi_q     <= (duty_cap != 8'd0);
                cnt      <= 8'd1;
            end else if (cnt == 8'hFF) begin
                duty_cap <= ((high_cnt + {4'd0, hi_pend}) >= HI_LIMIT) ? HI_LIMIT : duty_in;
                cnt      <= 8'd0;
                high_cnt <= 8'd0;
                hi_pend  <= 4'd0;
                hi_q     <= 1'b0;
            end else begin
                cnt      <= cnt + 8'd1;
                if (cnt[2:0] == 3'b111) begin
                    high_cnt <= high_cnt + {4'd0, hi_pend} + {7'd0, hi_q};
                    hi_pend  <= 4'd0;
                end else begin
                    hi_pend  <= hi_pend + {3'd0, hi_q};
                end
                hi_q     <= (cnt < duty_reg);
            end
        end

    assign pwm_out = (cnt < duty_reg);

    always @(posedge clk)
        if (pwm_out)
            assert (high_cnt < duty_reg);
endmodule

