module rr_arbiter_pri (
    input  wire       clk,
    input  wire       rst,
    input  wire       step,
    input  wire [3:0] req,
    output wire [3:0] gnt,
    output reg  [3:0] pri,
    output reg  [1:0] idx
);
    initial pri = 4'b0001;
    initial idx = 2'd0;

   reg [1:0] hold_cnt;   // cycles left in the current grant burst
   initial hold_cnt = 2'd0;

  reg        parked;     // arbiter folded to quiescent outputs while idle
  reg  [1:0] park_idx;   // rotating pointer position retained while parked
  initial parked = 1'b0;
  initial park_idx = 2'd0;

    // only the requester currently pointed at by the rotating priority wins
    assign gnt = req & pri;

    wire low_pri = pri[0] | pri[1];   // priority pointer sits in lower half
    wire idx_hi  = idx[1];            // binary index says upper half

   wire hold_active  = (hold_cnt != 2'd0);
   // a fresh grant opens a burst; the pointer moves on the last burst cycle,
   // or right away when the requester it points at has nothing pending
   wire burst_start  = (|gnt) && !hold_active;
   wire rotate       = step && ((hold_cnt == 2'd1) || (!hold_active && !(|gnt)));

  // nothing to serve: fold the pointer away into park_idx and drive the
  // outputs quiet; wake and reload the pointer when a request shows up
  wire idle    = (req == 4'b0000) && !hold_active;
  wire go_park = step && !parked && idle;
  wire wake    = step && parked && (req != 4'b0000);

    always @(posedge clk) begin
        if (rst) begin
            pri <= 4'b0001;
            idx <= 2'd0;
           hold_cnt <= 2'd0;
          parked   <= 1'b0;
          park_idx <= 2'd0;
       end else begin
          if (go_park) begin
              parked   <= 1'b1;
              park_idx <= idx;
              pri      <= 4'b0000;
              idx      <= 2'd0;
          end else if (wake) begin
              parked <= 1'b0;
              pri    <= (4'b0001 << park_idx);
              idx    <= park_idx;
          end else if (rotate && !parked) begin
              pri <= {pri[2:0], pri[3]};
              idx <= idx + 2'd1;
          end
           if (burst_start)
               hold_cnt <= 2'd3;
           else if (step && hold_active)
               hold_cnt <= hold_cnt - 2'd1;
       end
    end

    always @(posedge clk)
        if (|gnt)
            assert (!(low_pri && idx_hi));

   // the binary index must always name the requester that is being granted
   always @(posedge clk)
       if (|gnt)
           assert (gnt[idx]);
endmodule

