   // every eighth enabled operation the slice takes a double step, so the
   // accumulator keeps up with the externally scaled sample rate
   reg [2:0] phase;
   wire      dbl = (phase == 3'd7);


    initial o_result = 8'd0;
    initial half     = 7'd0;
   initial phase    = 3'd0;

    assign o_zero = (o_result == 8'd0);

    always @(posedge clk) begin
        if (rst) begin
            o_result <= 8'd0;
            half     <= 7'd0;
           phase    <= 3'd0;
        end else if (i_ce) begin
           o_result <= i_sub ? (o_result - (dbl ? 8'd4 : 8'd2))
                             : (o_result + (dbl ? 8'd4 : 8'd2));
