   // buffered in a 4-deep write FIFO
   reg  [2:0] fifo_lvl;
   reg        phase;
   reg        push, pop;
   reg  [3:0] rem_nxt;
   reg  [2:0] lvl_nxt;

   initial fifo_lvl = 3'd0;
   initial phase    = 1'b0;
   initial n_push   = 4'd0;
   initial n_pop    = 4'd0;

   always @(*) begin
       push    = ce && (remaining != 4'd0) && (fifo_lvl != 3'd4);
       pop     = ce && phase && (fifo_lvl != 3'd0);
       rem_nxt = push ? (remaining - 4'd1) : remaining;
       lvl_nxt = fifo_lvl + (push ? 3'd1 : 3'd0) - (pop ? 3'd1 : 3'd0);
   end

    always @(posedge clk) begin
        if (rst) begin
            remaining <= 4'd8;
            sent      <= 4'd0;
            busy      <= 1'b1;
            done      <= 1'b0;
fifo_lvl  <= 3'd0;
phase     <= 1'b0;
n_push    <= 4'd0;
n_pop     <= 4'd0;
        end else if (ce) begin
if (push) begin
    remaining <= rem_nxt;
    sent      <= sent + 4'd1;
end
fifo_lvl <= lvl_nxt;
phase    <= ~phase;
// the engine keeps claiming to copy until the source words are all
// fetched and the write FIFO has drained to the destination
busy     <= (rem_nxt != 4'd0) || (lvl_nxt != 3'd0);
