    output wire [3:0] grant,
    output wire [3:0] pop_ack,
    output wire [3:0] valid_top,
    output wire [3:0] busy
);
    // Shared depth budget for the four stacks.  A stack may only take a new
    // entry when the pool still has a free credit; the credit comes back when
    // the entry is popped again.
    localparam [3:0] TOTAL = 4'd8;

    initial pool = TOTAL;

    wire [2:0] sp0, sp1, sp2, sp3;
    wire [2:0] items0, items1, items2, items3;
    wire       t0, t1, t2, t3;
    wire       h0, h1, h2, h3;
    wire [3:0] np0, np1, np2, np3;
    wire [3:0] nq0, nq1, nq2, nq3;

    wire have_credit = (pool != 4'd0);

    // A stack that is already at its own limit does not ask for a credit.
    wire want0 = push_req[0] && !h0;
    wire want1 = push_req[1] && !h1;
    wire want2 = push_req[2] && !h2;
    wire want3 = push_req[3] && !h3;

    // Static priority arbiter: one credit is handed out per cycle at most.
    wire g0 = have_credit && want0;
    wire g1 = have_credit && want1 && !want0;
    wire g2 = have_credit && want2 && !want1 && !want0;
    wire g3 = have_credit && want3 && !want2 && !want1 && !want0;
    wire g_any = g0 || g1 || g2 || g3;

    // The stack core gives its push port priority over its pop port, so a
    // granted cycle never retires an entry.
    wire p0 = !g0 && pop_req[0] && (sp0 != 3'd0);
    wire p1 = !g1 && pop_req[1] && (sp1 != 3'd0);
    wire p2 = !g2 && pop_req[2] && (sp2 != 3'd0);
    wire p3 = !g3 && pop_req[3] && (sp3 != 3'd0);

    wire [2:0] returned = {2'b00, p0} + {2'b00, p1} + {2'b00, p2} + {2'b00, p3};

    always @(posedge clk) begin
        if (rst)
            pool <= TOTAL;
        else
            pool <= pool + {1'b0, returned} - {3'b000, g_any};
    end

    stack_occupancy u0 (
        .clk(clk), .rst(rst), .push(g0), .pop(pop_req[0]),
        .sp(sp0), .items(items0), .top_valid(t0),
        .n_push(np0), .n_pop(nq0), .full(h0)
    );

    stack_occupancy u1 (
        .clk(clk), .rst(rst), .push(g1), .pop(pop_req[1]),
        .sp(sp1), .items(items1), .top_valid(t1),
        .n_push(np1), .n_pop(nq1), .full(h1)
    );

    stack_occupancy u2 (
        .clk(clk), .rst(rst), .push(g2), .pop(pop_req[2]),
        .sp(sp2), .items(items2), .top_valid(t2),
        .n_push(np2), .n_pop(nq2), .full(h2)
    );

    stack_occupancy u3 (
        .clk(clk), .rst(rst), .push(g3), .pop(pop_req[3]),
        .sp(sp3), .items(items3), .top_valid(t3),
        .n_push(np3), .n_pop(nq3), .full(h3)
    );

    assign grant     = {g3, g2, g1, g0};
    assign pop_ack   = {p3, p2, p1, p0};
    assign valid_top = {t3, t2, t1, t0};
    assign busy      = {h3, h2, h1, h0};

    // Pool property: if every credit is back in the pool, no stack can still
    // be advertising a valid top entry.
    always @(posedge clk)
        if (pool == TOTAL)
            assert (!(t0 || t1 || t2 || t3));
endmodule

