module sorted_pair (
    input wire clk,
    input wire rst,
    input wire ins,
    input wire pop,
    input wire [3:0] val,
    output reg [4:0] sum
);
    reg [3:0] k0, k1;
    reg [1:0] count;
    reg [2:0] n_in, n_out;
    initial begin k0 = 0; k1 = 0; count = 0; sum = 0; end
    initial begin n_in = 0; n_out = 0; end

    // occupancy is tracked by the insert/pop event ledger; the difference of
    // the two wrapping counters is the live depth used for flow control
    wire [2:0] net_occ  = n_in - n_out;
    wire occ_full  = (net_occ == 3'd2);
    wire occ_empty = (net_occ == 3'd0);
    wire do_ins = ins && !pop && !occ_full;
    wire do_pop = pop && !ins && !occ_empty;

    always @(posedge clk) begin
        if (rst) begin
            k0 <= 4'd0; k1 <= 4'd0; count <= 2'd0; sum <= 5'd0;
            n_in <= 3'd0; n_out <= 3'd0;
        end else if (do_ins) begin
            if (count == 2'd0) begin
                k0 <= val;
            end else if (val < k0) begin
                k0 <= val; k1 <= k0;
            end else begin
                k1 <= val;
            end
            count <= count + 2'd1;
            sum   <= sum + {1'b0, val};
            n_in  <= n_in + 3'd1;
        end else if (do_pop) begin
            k0    <= k1;
            k1    <= 4'd0;
            count <= count - 2'd1;
            sum   <= sum - {1'b0, k0};
            n_out <= n_out + 3'd1;
        end
    end

    always @(posedge clk)
        if (count == 2'd0)
            assert (sum == 5'd0);
endmodule

