module pwm_dimmer_seq (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    input  wire [7:0] duty_in,
    output wire       pwm
);
    // free-running PWM phase counter
    reg [3:0] phase       = 4'd0;
    // rotating one-hot channel selector, advanced once per PWM period
    reg [3:0] chan_sel    = 4'b0001;
    // binary mirror of the selector position
    reg [1:0] idx         = 2'd0;
    // duty latched at the period boundary
    reg [7:0] duty_shadow = 8'd0;

   // channel B: auxiliary dimming engine, staggered two ring slots ahead of
   // channel A so the two banks are never driven in the same slot
   reg [3:0] sel_b       = 4'b0100;
   reg [3:0] duty_b      = 4'd0;

   // only one rotator is instantiated (in channel B); channel A taps the
   // same ring two slots behind it
   wire [3:0] sel_b_next = {sel_b[2:0], sel_b[3]};

   assign pwm = (phase < duty_shadow[7:4]) | (sel_b[0] & (phase < duty_b));

    wire period_end = ce && (phase == 4'd15);

    always @(posedge clk) begin
        if (rst) begin
            phase       <= 4'd0;
            chan_sel    <= 4'b0001;
            idx         <= 2'd0;
            duty_shadow <= 8'd0;
           sel_b       <= 4'b0100;
           duty_b      <= 4'd0;
        end else if (ce) begin
            phase <= phase + 4'd1;
            if (phase == 4'd15) begin
               sel_b       <= sel_b_next;
               chan_sel    <= {sel_b_next[1:0], sel_b_next[3:2]};
                idx         <= idx + 2'd1;
                duty_shadow <= duty_in;
               duty_b      <= duty_in[3:0];
            end
        end
    end

    // P: when the mirror index points at position 0, the one-hot selector
    //    must be sitting on channel 0.
    always @(posedge clk)
        if (idx == 2'd0)
            assert (chan_sel == 4'b0001);
endmodule

