module debounce_shadow (
    input  wire clk,
    input  wire rst,
    input  wire ce,      // sample enable: low => design idles, no state changes
    input  wire raw,     // raw (noisy) button input
    output reg  out      // debounced output
);
    // stability counter (binary) and its one-hot phase shadow
    reg [1:0] cnt;
    reg [3:0] oh;

    reg       sync;        // last sampled level
    reg       out_shadow;  // shadow copy of out, driven off the one-hot path
    reg       out_valid;   // set once a debounced decision has been taken
    reg [1:0] hold;        // minimum output hold: ce cycles left before out may move again

    initial begin
        cnt        = 2'd0;
        oh         = 4'b0001;
        sync       = 1'b0;
        out        = 1'b0;
        out_shadow = 1'b0;
        out_valid  = 1'b0;
        hold       = 2'd0;
    end

    wire match = (raw == sync);
    // a level accepted by the one-hot phase path, honouring the hold window
    wire accept = match && oh[3] && (hold == 2'd0);

    always @(posedge clk) begin
        if (rst) begin
            cnt        <= 2'd0;
            oh         <= 4'b0001;
            sync       <= raw;
            out        <= 1'b0;
            out_shadow <= 1'b0;
            out_valid  <= 1'b0;
            hold       <= 2'd0;
        end else if (ce) begin
            if (!match) begin
                // input changed: restart the stability measurement
                sync <= raw;
                cnt  <= 2'd0;
                oh   <= 4'b0001;
            end else begin
                // advance binary counter (saturating)
                if (cnt != 2'd3)
                    cnt <= cnt + 2'd1;
                // advance one-hot phase (saturating in the top position)
                if (!oh[3])
                    oh <= oh << 1;
                // decision taken from the BINARY path
                if (cnt == 2'd3 && hold == 2'd0) begin
                    out       <= sync;
                    out_valid <= 1'b1;
                end
                // decision taken from the ONE-HOT path
                if (accept)
                    out_shadow <= sync;
                // minimum output pulse width: reload on a real change, else run down
                if (accept && (sync != out_shadow))
                    hold <= 2'd3;
                else if (hold != 2'd0)
                    hold <= hold - 2'd1;
            end
        end
    end

    // P: once a debounced decision exists, the shadow must agree with the output
    always @(posedge clk)
        if (out_valid)
            assert (out == out_shadow);

    // P2: before the first debounced decision the shadow path and the hold timer are quiescent
    always @(posedge clk)
        if (!out_valid)
            assert (!out_shadow && hold == 2'd0);
endmodule

