   // tighten it when a request finds the bucket dry
   wire cap_up = drip  && (tok_stage == cap)  && (cap != 3'd4);
   wire cap_dn = spend && !drip && (tok_stage == 3'd0) && (cap != 3'd0);

    initial tokens   = 3'd0;
initial tok_stage = 3'd0;
initial cap = 3'd2;
    initial tokens_hi = 1'b0;

