module vend_credit (
    input  wire clk,
    input  wire i_rst,
    input  wire i_nickel,
    input  wire i_dime,
    output wire o_dispense
);
    // credit counted in 5-cent units toward a 25c (5 unit) item
    reg [2:0] units;
    reg [4:0] credit_1h;   // one-hot shadow of the credit level
   reg [2:0] nkl;         // nickels held in the escrow, available as change
    initial units     = 3'd0;
    initial credit_1h = 5'b00001;
   initial nkl       = 3'd0;

   wire       coin    = i_nickel | i_dime;
    wire [2:0] amount = i_dime ? 3'd2 : 3'd1;
    wire [3:0] sum    = units + amount;

   // 30c tendered for a 25c item owes a nickel back, so the mech only takes
   // that coin when the escrow still holds a nickel it can return
   wire       overpay = coin && (sum == 4'd6);
   wire       refuse  = overpay && (nkl == 3'd0);
   wire       step    = coin && !refuse;

    assign o_dispense = step && (sum >= 4'd5);

    always @(posedge clk)
        if (i_rst) begin
            units     <= 3'd0;
            credit_1h <= 5'b00001;
           nkl       <= 3'd0;
        end else if (step) begin
            if (sum >= 4'd5) begin
                units     <= 3'd0;          // vend and clear credit
                credit_1h <= 5'b00001;
               nkl       <= 3'd0;          // escrow dumped, change paid out
            end else begin
                units     <= sum[2:0];
                credit_1h <= i_dime ? (credit_1h << 2) : (credit_1h << 1);
               nkl       <= i_dime ? nkl : (nkl + 3'd1);
            end
        end

    // P: outside reset the credit shadow is always exactly one-hot
    always @(*)
        if (!i_rst)
            assert ((credit_1h != 5'b00000) &&
                    ((credit_1h & (credit_1h - 5'b00001)) == 5'b00000));

   // P2: the escrow can never hold more nickels than the credit level it
   // helped build, so the shadow bit always survives a shift down by nkl
   always @(posedge clk)
       if (!i_rst)
           assert ((credit_1h >> nkl) != 5'b00000);
endmodule

