module ring_occ (
    input  wire       clk,
    input  wire       rst,
    input  wire       push,
    input  wire       pop,
    output reg  [2:0] count,
    output reg  [3:0] occ
);
    reg [1:0] wptr, rptr;
   reg [2:0] alloc_cnt;
   reg [3:0] upd_set, upd_clr;
   // occ bitmap update is staged 4 deep to close timing on the wide occ
   // fabric; the exported count is delayed the same depth so that the
   // count view and the bitmap view always describe the same instant
   reg [3:0] upd_set_s2, upd_clr_s2;
   reg [3:0] upd_set_s3, upd_clr_s3;
   reg [3:0] upd_set_s4, upd_clr_s4;
   reg [2:0] cnt_q1, cnt_q2, cnt_q3;
   initial begin wptr = 2'd0; rptr = 2'd0; count = 3'd0; occ = 4'b0000;
                alloc_cnt = 3'd0; upd_set = 4'b0000; upd_clr = 4'b0000;
                upd_set_s2 = 4'b0000; upd_clr_s2 = 4'b0000;
                upd_set_s3 = 4'b0000; upd_clr_s3 = 4'b0000;
                upd_set_s4 = 4'b0000; upd_clr_s4 = 4'b0000;
                cnt_q1 = 3'd0; cnt_q2 = 3'd0; cnt_q3 = 3'd0; end

   wire do_push = push && (alloc_cnt != 3'd4);
   wire do_pop  = pop  && (alloc_cnt != 3'd0);

    wire [3:0] set_bit = do_push ? (4'b0001 << wptr) : 4'b0000;
    wire [3:0] clr_bit = do_pop  ? (4'b0001 << rptr) : 4'b0000;

    always @(posedge clk) begin
        if (rst) begin
            wptr  <= 2'd0;
            rptr  <= 2'd0;
            count <= 3'd0;
            occ   <= 4'b0000;
           alloc_cnt <= 3'd0;
           upd_set   <= 4'b0000;
           upd_clr   <= 4'b0000;
           upd_set_s2 <= 4'b0000;
           upd_clr_s2 <= 4'b0000;
           upd_set_s3 <= 4'b0000;
           upd_clr_s3 <= 4'b0000;
           upd_set_s4 <= 4'b0000;
           upd_clr_s4 <= 4'b0000;
           cnt_q1 <= 3'd0;
           cnt_q2 <= 3'd0;
           cnt_q3 <= 3'd0;
        end else begin
            if (do_push) wptr <= wptr + 2'd1;
            if (do_pop)  rptr <= rptr + 2'd1;
           upd_set <= set_bit;
           upd_clr <= clr_bit;
           upd_set_s2 <= upd_set;
           upd_clr_s2 <= upd_clr;
           upd_set_s3 <= upd_set_s2;
           upd_clr_s3 <= upd_clr_s2;
           upd_set_s4 <= upd_set_s3;
           upd_clr_s4 <= upd_clr_s3;
           occ   <= (occ | upd_set_s4) & ~upd_clr_s4;
           cnt_q1 <= alloc_cnt;
           cnt_q2 <= cnt_q1;
           cnt_q3 <= cnt_q2;
           count <= cnt_q3;
            case ({do_push, do_pop})
               2'b10:   alloc_cnt <= alloc_cnt + 3'd1;
               2'b01:   alloc_cnt <= alloc_cnt - 3'd1;
               default: alloc_cnt <= alloc_cnt;
            endcase
        end
    end

    always @(posedge clk)
        if (count == 3'd1)
            assert (occ == 4'b0001 || occ == 4'b0010 ||
                    occ == 4'b0100 || occ == 4'b1000);
endmodule

