module lfsr_shadow_capture (
    input  wire       i_clk,
    input  wire       i_rst,
    input  wire       i_ce,
    input  wire       i_cap,
    output wire [7:0] o_rand,
    output wire [7:0] o_shadow,
    output wire       o_shadow_valid
);
    // maximal-length 8-bit LFSR, taps at 8,6,5,4 (x^8 + x^6 + x^5 + x^4 + 1)
    reg [7:0] lfsr;
    reg [7:0] shadow;
    reg       shadow_valid;
   reg [7:0] stage;
   reg       stage_full;
   reg [3:0] n_ld;
   reg [3:0] n_mv;

    initial lfsr         = 8'h01;
    initial shadow       = 8'h00;
    initial shadow_valid = 1'b0;
   initial stage      = 8'h00;
   initial stage_full = 1'b0;
   initial n_ld       = 4'd0;
   initial n_mv       = 4'd0;

    wire fb = lfsr[7] ^ lfsr[5] ^ lfsr[4] ^ lfsr[3];

   // capture pipeline: a request stages one sample, the stage then drains
   // into the shadow register on the following enabled cycle
   wire ld_en = i_ce && i_cap && !stage_full;
   wire mv_en = i_ce && (n_ld != n_mv);

    always @(posedge i_clk) begin
        if (i_rst) begin
            lfsr <= 8'h01;
        end else if (i_ce) begin
            lfsr <= { lfsr[6:0], fb };
        end
    end

    // shadow register: snapshots the generator output on request
    always @(posedge i_clk) begin
        if (i_rst) begin
            shadow       <= 8'h00;
            shadow_valid <= 1'b0;
end else if (mv_en) begin
shadow       <= stage;
            shadow_valid <= 1'b1;
        end
    end

   // staging buffer for the capture pipeline
   always @(posedge i_clk) begin
       if (i_rst) begin
           stage      <= 8'h00;
           stage_full <= 1'b0;
       end else if (ld_en) begin
           stage      <= lfsr;
           stage_full <= 1'b1;
       end else if (mv_en) begin
           stage_full <= 1'b0;
       end
   end

   // pipeline ledger: loads into and moves out of the staging buffer
   always @(posedge i_clk) begin
       if (i_rst) begin
           n_ld <= 4'd0;
           n_mv <= 4'd0;
       end else begin
           if (ld_en) n_ld <= n_ld + 4'd1;
           if (mv_en) n_mv <= n_mv + 4'd1;
       end
   end

    assign o_rand         = lfsr;
    assign o_shadow       = shadow;
    assign o_shadow_valid = shadow_valid;

    // P: once a sample has been latched, it can never be the lockup word
    always @(*)
        if (shadow_valid)
            assert (shadow != 8'h00);
endmodule

