module dma_copier (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    output reg  [3:0] remaining,
    output reg  [3:0] sent,
    output reg        busy,
    output reg        done
);
    // the bus grants at most five words per burst, so an 8-word block is
    // issued as a 5-word burst plus a deferred 3-word tail
    reg  [3:0] pending;
   // the write port is half-width, so a staged word retires on alternate
   // cycles; a 2-entry buffer absorbs the fetch/retire rate difference
   reg  [3:0] inflight;
   reg        wr_phase;
   wire drain = wr_phase && (inflight != 4'd0);
   wire fetch = (remaining != 4'd0) && ((inflight != 4'd2) || drain);
    // block length is fixed at 8 words
    initial remaining = 4'd5;
    initial pending   = 4'd3;
    initial sent      = 4'd0;
    initial busy      = 1'b1;
    initial done      = 1'b0;
   initial inflight  = 4'd0;
   initial wr_phase  = 1'b0;

    always @(posedge clk) begin
        if (rst) begin
            remaining <= 4'd5;
            pending   <= 4'd3;
            sent      <= 4'd0;
            busy      <= 1'b1;
            done      <= 1'b0;
           inflight  <= 4'd0;
           wr_phase  <= 1'b0;
        end else if (ce) begin
           wr_phase <= ~wr_phase;
           if (drain)
               sent <= sent + 4'd1;
           inflight <= inflight + (fetch ? 4'd1 : 4'd0) - (drain ? 4'd1 : 4'd0);
           if (fetch) begin
                remaining <= remaining - 4'd1;
            end
           else if (remaining == 4'd0 && pending != 4'd0) begin
                // burst boundary: re-arm the engine for the deferred tail
                remaining <= pending;
                pending   <= 4'd0;
                busy      <= 1'b1;
            end
           // the engine stays busy until the staging buffer has drained
           else if (drain && inflight == 4'd1)
               busy <= 1'b0;
            // done is raised the cycle after the last word retires
           done <= (remaining == 4'd0 && pending == 4'd0 && inflight == 4'd0);
        end
    end

    // P: the engine must never report completion while still claiming to copy
    always @(posedge clk)
        if (done)
            assert (!busy);
endmodule

