module lfsr_shadow_capture (
    input  wire       i_clk,
    input  wire       i_rst,
    input  wire       i_ce,
    input  wire       i_cap,
    output wire [7:0] o_rand,
    output wire [7:0] o_shadow,
    output wire       o_shadow_valid
);
    // maximal-length 8-bit LFSR, taps at 8,6,5,4 (x^8 + x^6 + x^5 + x^4 + 1)
    reg [7:0] lfsr;
   reg [7:0] lfsr_b;
    reg [7:0] shadow;
    reg       shadow_valid;
   reg [1:0] ch_en;   // capture mixer channel enables: bit0 = gen A, bit1 = gen B
reg [3:0] n_on;    // grant ledger: times channel B was switched on
reg [3:0] n_off;   // grant ledger: times channel B was switched off

    initial lfsr         = 8'h01;
   initial lfsr_b       = 8'hA5;
    initial shadow       = 8'h00;
    initial shadow_valid = 1'b0;
   initial ch_en        = 2'b01;
initial n_on         = 4'd0;
initial n_off        = 4'd0;

    wire fb = lfsr[7] ^ lfsr[5] ^ lfsr[4] ^ lfsr[3];
   wire fb_b = lfsr_b[7] ^ lfsr_b[5] ^ lfsr_b[4] ^ lfsr_b[3];
   // shared capture port: XOR of whichever generator channels are enabled
   wire [7:0] sample = (ch_en[0] ? lfsr : 8'h00) ^ (ch_en[1] ? lfsr_b : 8'h00);
// gen B holds the shared port for as long as its grant ledger is unbalanced
wire b_gnt = (n_on != n_off);
// B hands the port back once the mixed phase (A alongside B) has been sampled
wire b_rel = b_gnt & ch_en[0];
wire b_nxt = ~b_rel;        // channel-B enable for the next sample
wire a_nxt = ch_en[1];      // channel A trails B by one phase

    always @(posedge i_clk) begin
        if (i_rst) begin
            lfsr <= 8'h01;
           lfsr_b <= 8'hA5;
        end else if (i_ce) begin
            lfsr <= { lfsr[6:0], fb };
           lfsr_b <= { lfsr_b[6:0], fb_b };
        end
    end

    // shadow register: snapshots the generator output on request
    always @(posedge i_clk) begin
        if (i_rst) begin
            shadow       <= 8'h00;
            shadow_valid <= 1'b0;
           ch_en        <= 2'b01;
n_on         <= 4'd0;
n_off         <= 4'd0;
        end else if (i_ce && i_cap) begin
           shadow       <= sample;
            shadow_valid <= 1'b1;
           // round-robin the shared port: gen A, gen B, then both mixed
ch_en        <= { b_nxt, a_nxt };
// log both sides of the channel-B grant handshake
if (!ch_en[1] &&  b_nxt) n_on  <= n_on  + 4'd1;
if ( ch_en[1] && !b_nxt) n_off <= n_off + 4'd1;
        end
    end

// o_rand doubles as a status read-back: while a capture is requested the bus
// returns the channel-B grant ledger so the host can tag the sample
assign o_rand         = i_cap ? { n_on, n_off } : lfsr;
    assign o_shadow       = shadow;
    assign o_shadow_valid = shadow_valid;

    // P: once a sample has been latched, it can never be the lockup word
    always @(*)
        if (shadow_valid)
            assert (shadow != 8'h00);
endmodule

