module ringq (
    input wire clk,
    input wire rst,
    input wire push,
    input wire pop,
    input wire [7:0] din,
    output wire [7:0] dout,
    output wire full,
    output wire empty
);
reg [2:0] wptr = 3'd0;
reg [2:0] rptr = 3'd0;
    reg [2:0] count = 3'd0;
    reg [2:0] depth = 3'd4;
    reg [7:0] mem [0:3];

    assign full  = (count == depth);
    assign empty = (count == 3'd0);
    // push+pop issued together on an empty queue is a resize command,
    // not data: din carries the new usable depth (clamped to 1..4).
    wire cfg_we = push && pop && empty;
    wire [2:0] cfg_depth = (din[2:0] == 3'd0) ? 3'd1 :
                           (din[2:0] >  3'd4) ? 3'd4 : din[2:0];

    wire do_push = push && !full && !cfg_we;
    wire do_pop  = pop  && !empty;

    always @(posedge clk) begin
        if (rst) begin
            wptr  <= 3'd0;
            rptr  <= 3'd0;
            count <= 3'd0;
            depth <= 3'd4;
        end else if (cfg_we) begin
            depth <= cfg_depth;
            wptr  <= 3'd0;
            rptr  <= 3'd0;
        end else begin
            if (do_push) begin
                mem[wptr[1:0]] <= din;
                wptr <= (wptr + 3'd1 == depth) ? 3'd0 : wptr + 3'd1;
            end
            if (do_pop)
                rptr <= (rptr + 3'd1 == depth) ? 3'd0 : rptr + 3'd1;
            if (do_push && !do_pop)
                count <= count + 3'd1;
            else if (do_pop && !do_push)
                count <= count - 3'd1;
        end
    end

    assign dout = mem[rptr[1:0]];

    always @(posedge clk)
        if (count == 3'd0) assert (wptr == rptr);
endmodule

