module uart_tx_budget (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // baud tick / enable: low means idle
    input  wire       i_start,
    input  wire [7:0] i_data,
    output reg        tx,
    output reg        busy
);
    // bit accounting for one 8-bit payload
    reg [3:0] sent;   // data bits already shifted out
    reg [3:0] left;    // data bits still to shift out
    reg [7:0] sh;      // shift register
   reg [3:0] sh_cnt;  // payload bits still sitting inside the shift register
   reg       obuf;    // output stage: line level registered one tick ahead
   reg       obuf_v;  // output stage currently holds a payload bit
  reg       obuf2;   // second output stage: bit queued behind obuf
  reg       obuf2_v; // second output stage currently holds a payload bit

    initial tx   = 1'b1;
    initial busy = 1'b0;
    initial sent = 4'd0;
    initial left = 4'd8;
    initial sh   = 8'h00;
   initial sh_cnt = 4'd0;
   initial obuf   = 1'b1;
   initial obuf_v = 1'b0;
  initial obuf2   = 1'b1;
  initial obuf2_v = 1'b0;

    always @(posedge clk) begin
        if (rst) begin
            tx   <= 1'b1;
            busy <= 1'b0;
            sent <= 4'd0;
            left <= 4'd8;
            sh   <= 8'h00;
           sh_cnt <= 4'd0;
           obuf   <= 1'b1;
           obuf_v <= 1'b0;
          obuf2   <= 1'b1;
          obuf2_v <= 1'b0;
        end else if (i_ce) begin
            if (!busy) begin
                if (i_start) begin
                    busy <= 1'b1;
                  sh     <= {2'b00, i_data[7:2]};
                   obuf   <= i_data[0];   // prefetch bit 0 during the start bit
                  obuf2  <= i_data[1];   // and bit 1 queued behind it
                   obuf_v <= 1'b1;
                  obuf2_v <= 1'b1;
                  sh_cnt <= 4'd6;
                    sent <= 4'd0;
                    left <= 4'd8;
                    tx   <= 1'b0;      // start bit
                end else begin
                    tx   <= 1'b1;      // line idle high
                end
            end else if (left != 4'd0) begin
               tx   <= obuf;          // data bit out of the output stage
               sent <= sent + {3'b000, obuf_v};
                left <= left - 4'd1;
               if (sh_cnt != 4'd0) begin
                  obuf   <= obuf2;
                  obuf2  <= sh[0];
                   sh     <= {1'b0, sh[7:1]};
                   sh_cnt <= sh_cnt - 4'd1;
                  obuf_v  <= obuf2_v;
                  obuf2_v <= 1'b1;
               end else begin
                  obuf    <= obuf2;
                  obuf_v  <= obuf2_v;  // last queued bit moves up a stage
                  obuf2_v <= 1'b0;     // shifter drained
               end
            end else begin
                tx   <= 1'b1;          // stop bit, frame complete
                busy <= 1'b0;
            end
        end
    end

    // Property: whenever the transmitter reports no data bits remaining while a
    // frame is still active, exactly eight payload bits must have been shifted.
    always @(posedge clk)
        if (busy && left == 4'd0)
            assert (sent == 4'd8);
endmodule

