module watchdog (
    input wire clk,
    input wire rst,
    input wire i_ce,
    input wire kick,
    input wire ack,
    output reg fault
);
    reg [3:0] timer;
    reg [3:0] elapsed;
reg [3:0] period;
localparam [3:0] GRACE_TICKS = 4'd2;
reg [3:0] grace;
wire [3:0] period_tight = (period == 4'd4) ? 4'd4 : period - 4'd1;
wire [3:0] period_relax = (period == 4'd8) ? 4'd8 : period + 4'd1;
wire [3:0] remain       = timer + grace;
wire [3:0] reload_tight = period_tight - GRACE_TICKS;
wire [3:0] reload_relax = period_relax - GRACE_TICKS;
wire [3:0] reload_hold  = period - GRACE_TICKS;
initial begin timer = 4'd6; grace = GRACE_TICKS; elapsed = 4'd0; fault = 1'b0; period = 4'd8; end

    always @(posedge clk) begin
        if (rst) begin
timer   <= 4'd6;
grace   <= GRACE_TICKS;
            elapsed <= 4'd0;
            fault   <= 1'b0;
period  <= 4'd8;
        end else if (i_ce) begin
            if (ack) begin
timer   <= reload_tight;
grace   <= GRACE_TICKS;
period  <= period_tight;
                elapsed <= 4'd0;
                fault   <= 1'b0;
            end else if (kick && !fault) begin
if (timer == 4'd0) begin
timer  <= reload_hold;
grace  <= GRACE_TICKS;
end else begin
timer  <= reload_relax;
grace  <= GRACE_TICKS;
period <= period_relax;
end
                elapsed <= 4'd0;
            end else begin
                if (timer != 4'd0)   timer   <= timer - 4'd1;
else if (grace != 4'd0) grace <= grace - 4'd1;
if (elapsed != period) elapsed <= elapsed + 4'd1;
if (remain == 4'd1)   fault   <= 1'b1;
            end
        end
    end

    always @(posedge clk)
        if (elapsed == 4'd8)
            assert (fault);
endmodule

