module rr_arbiter_pri (
    input  wire       clk,
    input  wire       rst,
    input  wire       step,
    input  wire [3:0] req,
    output wire [3:0] gnt,
    output reg  [3:0] pri,
    output reg  [1:0] idx
);
    initial pri = 4'b0001;
    initial idx = 2'd0;

   // Requesters are grouped in pairs, {req[1:0]} and {req[3:2]}.  The pointer
   // walks both members of the selected pair before handing the turn over to
   // the other pair, so the rotation is held as a pair select plus a slot
   // inside that pair; idx is just the flattened pointer published outside.
   reg pair_sel;
   reg slot;
   initial pair_sel = 1'b0;
   initial slot = 1'b0;

   wire pair_wrap = slot;                  // slot 1 is the last member of a pair
   wire pair_nxt  = pair_sel ^ pair_wrap;
   wire slot_nxt  = ~slot;

    // only the requester currently pointed at by the rotating priority wins
    assign gnt = req & pri;

    wire low_pri = pri[0] | pri[1];   // priority pointer sits in lower half
    wire idx_hi  = idx[1];            // binary index says upper half

    always @(posedge clk) begin
        if (rst) begin
            pri <= 4'b0001;
            idx <= 2'd0;
           pair_sel <= 1'b0;
           slot <= 1'b0;
        end else if (step) begin
            pri <= {pri[2:0], pri[3]};
           pair_sel <= pair_nxt;
           slot <= slot_nxt;
           idx <= {pair_nxt, slot_nxt};
        end
    end

    always @(posedge clk)
        if (|gnt)
            assert (!(low_pri && idx_hi));
endmodule

