module wdog_kick (
    input wire clk,
    input wire i_ce,
    input wire kick,
    input wire ack,
    output wire o_reset
);
    reg [3:0] cnt;
    reg zf, armed, fault;
    reg [1:0] hold;
   reg [1:0] frac;                 // sub-tick prescaler of the service window
    initial cnt   = 4'd0;
    initial zf    = 1'b1;
    initial armed = 1'b0;
    initial fault = 1'b0;
    initial hold  = 2'd0;
   initial frac  = 2'd0;

    always @(posedge clk) if (i_ce) begin
        if (ack) begin
            fault <= 1'b0;
            armed <= 1'b0;
            cnt   <= 4'd0;
            zf    <= 1'b1;
           frac  <= 2'd0;
        end else if (kick && !fault) begin
            armed <= 1'b1;
            cnt   <= 4'd8;
            zf    <= 1'b0;
           frac  <= 2'd3;          // 8 coarse ticks of 4 ce pulses each
        end else if (armed) begin
            if (zf) fault <= 1'b1;            // expiry seen through the flag
           if (cnt == 4'd0 && frac == 2'd0) armed <= 1'b0; // whole window elapsed
           else if (frac != 2'd0) begin
               frac <= frac - 2'd1;
               zf   <= (cnt == 4'd0) && (frac == 2'd1);
           end else begin
                cnt <= cnt - 4'd1;
               frac <= 2'd3;
               zf   <= 1'b0;
            end
        end
    end

    // minimum reset assertion width: downstream blocks need o_reset wide, so
    // the fault latch is stretched by a shadow timer for a few ce ticks after
    // the host acknowledges it
    always @(posedge clk) if (i_ce) begin
        if (fault)             hold <= 2'd3;
        else if (hold != 2'd0) hold <= hold - 2'd1;
    end

    assign o_reset = fault || (hold != 2'd0);

    always @(*)
        if (fault) assert (!armed);

    // a pending fault means the service window timer is parked at zero
    always @(posedge clk)
        if (fault) assert (cnt == 4'd0);
endmodule

