module debounce_stability (
    input wire clk,
    input wire rst,
    input wire sample,
    input wire raw,
    output reg out
);
    reg [2:0] cnt;   // consecutive samples disagreeing with out
    reg [2:0] rem;   // samples still required before out may flip
    reg [2:0] cred;  // progress banked across brief re-agreements

    initial out = 1'b0;
    initial cnt = 3'd0;
    initial rem = 3'd4;
    initial cred = 3'd0;

    always @(posedge clk) begin
        if (rst) begin
            out <= 1'b0;
            cnt <= 3'd0;
            rem <= 3'd4;
            cred <= 3'd0;
        end else if (sample) begin
            if (raw == out) begin
                // brief re-agreement: bank what the streak achieved,
                // leaking one sample so stale progress decays away
                cnt <= 3'd0;
                if (cnt + cred == 3'd0) begin
                    cred <= 3'd0;
                    rem  <= 3'd4;
                end else begin
                    cred <= cnt + cred - 3'd1;
                    rem  <= rem + 3'd1;
                end
            end else if (cnt + cred == 3'd4) begin
                out <= raw;
                cnt <= 3'd0;
                cred <= 3'd0;
                rem <= 3'd4;
            end else begin
                cnt <= cnt + 3'd1;
                rem <= rem - 3'd1;
            end
        end
    end

    always @(posedge clk)
        if (cnt == 3'd4) assert (rem != 3'd4);
endmodule

