module alu_budget (
    input wire clk,
    input wire rst,
    input wire i_ce,
    input wire [7:0] i_step,
    output wire [7:0] o_acc,
    output wire o_zero,
    output wire o_full,
    output wire [7:0] o_resv,
    output wire [3:0] o_take,
    output wire [3:0] o_give
);
    localparam [7:0] LIMIT = 8'd200;

    reg [7:0] acc;   // accumulated result
    reg [7:0] rem;   // headroom credited to the accumulator
    reg [7:0] resv;   // operand held between the headroom debit and the accumulate
    reg [3:0] n_take; // reservations debited out of the headroom
    reg [3:0] n_give; // reservations folded into the accumulator
    initial acc = 8'd0;
    initial rem = LIMIT;
    initial resv = 8'd0;
    initial n_take = 4'd0;
    initial n_give = 4'd0;

    wire pending = (n_take != n_give);
    wire grant = i_ce && !pending && (i_step != 8'd0) && (rem >= i_step);
    wire fold = i_ce && pending;

    always @(posedge clk)
        if (rst) begin
            acc <= 8'd0;
            rem <= LIMIT;
            resv <= 8'd0;
            n_take <= 4'd0;
            n_give <= 4'd0;
        end else begin
            if (grant) begin
                rem <= rem - i_step;
                resv <= i_step;
                n_take <= n_take + 4'd1;
            end
            if (fold) begin
                acc <= acc + resv;
                resv <= 8'd0;
                n_give <= n_give + 4'd1;
            end
        end

    assign o_acc  = acc;
    assign o_zero = (acc == 8'd0);
    assign o_full = (rem == 8'd0);
    assign o_resv = resv;
    assign o_take = n_take;
    assign o_give = n_give;

    // P: a nonzero accumulation never exceeds its saturation bound
    always @(*)
        if (!o_zero) assert (acc <= LIMIT);
