module vend_credit (
    input wire clk,
    input wire i_reset,
    input wire i_ce,
    input wire i_dime,
    output wire o_dispense,
    output wire [5:0] o_change
);
    reg [3:0] units = 0;      // credit in 5-cent units
    reg [5:0] cents = 0;      // credit in cents
    reg       dispense = 0;
    reg [5:0] change = 0;
    reg [5:0] chg_stage = 0;   // vend total waiting on the change subtractor
    reg       vend_stage = 0;  // a vend was deducted from credit last cycle
   reg [2:0] n_units_in  = 0; // coin ledger: nickel-equivalents taken in
   reg [2:0] n_units_out = 0; // coin ledger: nickel-equivalents paid out by vends

    wire [3:0] inc_u = i_dime ? 4'd2  : 4'd1;
    wire [5:0] inc_c = i_dime ? 6'd10 : 6'd5;
    wire [3:0] nu = units + inc_u;
    wire [5:0] nc = cents + inc_c;
   wire [2:0] inc_n = i_dime ? 3'd2 : 3'd1;
   // credit the ledger says we hold once this coin has been counted
   wire [2:0] nl = (n_units_in - n_units_out) + inc_n;
   // the change subtractor is fed from the audited ledger, converted to cents
   wire [5:0] vend_total = {nl, 2'b00} + {3'b000, nl};

    always @(posedge clk)
        if (i_reset) begin
            units    <= 4'd0;
            cents    <= 6'd0;
            dispense <= 1'b0;
            change   <= 6'd0;
            chg_stage  <= 6'd0;
            vend_stage <= 1'b0;
           n_units_in  <= 3'd0;
           n_units_out <= 3'd0;
        end else if (i_ce) begin
            // stage 2: finish the change subtraction started last cycle
            dispense <= vend_stage;
            if (vend_stage) change <= chg_stage - 6'd25;
            // stage 1: take the coin and deduct a full vend's worth of credit
           n_units_in <= n_units_in + inc_n;
            if (nu >= 4'd5) begin
               n_units_out <= n_units_out + 3'd5;
                units    <= nu - 4'd5;
                cents    <= nc - 6'd25;
               chg_stage  <= vend_total;
                vend_stage <= 1'b1;
            end else begin
                units    <= nu;
                cents    <= nc;
                vend_stage <= 1'b0;
            end
        end

    assign o_dispense = dispense;
