    reg [3:0] elapsed;
reg [3:0] resv;
reg [3:0] wresv;
reg [3:0] period;
wire [3:0] period_tight = (period == 4'd4) ? 4'd4 : period - 4'd1;
wire [3:0] period_relax = (period == 4'd8) ? 4'd8 : period + 4'd1;
localparam [3:0] GRACE = 4'd2;
localparam [3:0] WARN = 4'd1;
initial begin timer = 4'd8; elapsed = 4'd0; fault = 1'b0; period = 4'd8; resv = 4'd0; wresv = 4'd0; end

    always @(posedge clk) begin
        if (rst) begin
            timer   <= 4'd8;
            elapsed <= 4'd0;
            fault   <= 1'b0;
period  <= 4'd8;
            resv    <= 4'd0;
            wresv   <= 4'd0;
