module token_bucket (
    input  wire clk,
    input  wire rst,
    input  wire ce,
    input  wire req,
    input  wire drip,
    output wire grant
);
    reg [3:0] tokens = 4'd8;   // tokens currently in the bucket
    reg [3:0] free   = 4'd0;   // room left in the bucket (shadow accounting)

   reg [3:0] n_out  = 4'd0;   // ledger: tokens handed out (free-running, wraps)
   reg [3:0] n_in   = 4'd0;   // ledger: tokens dripped in (free-running, wraps)

    wire spend   = ce && req  && (tokens != 4'd0);
    wire refill  = ce && drip && (free   != 4'd0);

   // Idle maintenance cycle: enabled but nothing requested and nothing
   // dripping.  The shadow room count is re-derived from the event ledger
   // so that it cannot drift away from the traffic actually seen.
   wire audit = ce && !req && !drip;

    assign grant = spend;

    always @(posedge clk) begin
        if (rst) begin
            tokens <= 4'd8;
            free   <= 4'd0;
           n_out  <= 4'd0;
           n_in   <= 4'd0;
        end else begin
            tokens <= tokens - spend + refill;
           if (audit)
               free <= n_out - n_in;
           else
               free <= free + spend - refill;
           n_out <= n_out + spend;
           n_in  <= n_in  + refill;
        end
    end

    // P: if the bucket is not completely full, at least one slot's worth of
    // tokens is missing, so occupancy cannot exceed CAP-1.
    always @(posedge clk)
        if (free != 4'd0)
            assert (tokens <= 4'd7);
endmodule

