module wdog_gray_mon (
    input  wire i_clk,
    input  wire i_rst,
    input  wire i_ce,      // idle condition: all state frozen when low
    input  wire i_arm,     // Q: opens the monitoring window
    input  wire i_ack,     // R: closes the monitoring window
    output wire o_bite,
    output wire o_grace,
    output wire o_sys_reset
);
    // ---- timer domain: free running gray coded tick pointer -------------
    reg [2:0] cnt;   // binary tick counter
    reg [2:0] g;     // registered gray code of cnt

// ---- monitor domain: three flop synchronizer on the gray pointer ----
// s3 keeps the previous stable sample so the monitor can tell whether
// the timer pointer is still advancing.
reg [2:0] s1, s2, s3;

    // ---- window / latched reset ----------------------------------------
    reg armed;
    reg rst_latch;

    initial cnt       = 3'd0;
    initial g         = 3'd0;
    initial s1        = 3'd0;
    initial s2        = 3'd0;
initial s3        = 3'd0;
    initial armed     = 1'b0;
    initial rst_latch = 1'b0;

    wire [2:0] nxt = cnt + 3'd1;

    always @(posedge i_clk)
        if (i_rst) begin
            cnt <= 3'd0;
            g   <= 3'd0;
        end else if (i_ce) begin
            cnt <= nxt;
            g   <= nxt ^ (nxt >> 1);
        end

    always @(posedge i_clk)
        if (i_rst) begin
            s1 <= 3'd0;
            s2 <= 3'd0;
s3 <= 3'd0;
        end else if (i_ce) begin
            s1 <= g;    // first flop: freshly captured pointer
            s2 <= s1;   // second flop: stable pointer sample
s3 <= s2;   // previous stable sample, for tick detection
        end

    // gray -> binary decode of both synchronizer stages
    wire [2:0] mon = { s2[2], s2[2]^s2[1], s2[2]^s2[1]^s2[0] };
    wire [2:0] pre = { s1[2], s1[2]^s1[1], s1[2]^s1[1]^s1[0] };
wire [2:0] mon_q = { s3[2], s3[2]^s3[1], s3[2]^s3[1]^s3[0] };

// the pointer must advance every enabled cycle; if the stable sample
// repeats, the timer side has stopped ticking
wire stall = (s2 == s3);

    // terminal count seen on the stable sample -> watchdog bites
    assign o_bite  = (mon == 3'd7);
    // deep inside the grace region on the freshly captured sample
    assign o_grace = (pre == 3'd2);

    assign o_sys_reset = rst_latch;

    always @(posedge i_clk)
        if (i_rst) begin
            armed     <= 1'b0;
            rst_latch <= 1'b0;
        end else if (i_ce) begin
            if (i_ack)      armed <= 1'b0;
            else if (i_arm) armed <= 1'b1;

            if (i_ack)                     rst_latch <= 1'b0;
else if (armed && (o_bite || stall)) rst_latch <= 1'b1;
        end

    // P: inside the monitoring window the bite and grace indications are
    // never asserted together.
    always @(posedge i_clk)
        if (armed)
            assert (!(o_bite && o_grace));

    // P2: inside the monitoring window the freshly captured sample can
    // never sit deep in the grace region while the previous stable
    // sample still reads terminal count.
    always @(posedge i_clk)
        if (armed)
            assert (!(o_grace && (mon_q == 3'd7)));
endmodule

