module credit_deadline (
    input  wire clk,
    input  wire i_ce,      // global enable: low => all state frozen
    input  wire rst,
    input  wire req,       // producer wants to spend a credit
    output wire grant,
    output wire busy
);
    localparam [2:0] TOTAL = 3'd4;   // configured credit pool

    // credits held by the producer, credits outstanding at the consumer
    reg [2:0] credits;
    reg [2:0] outst;
    // consumer needs two enabled cycles to retire one outstanding credit
    reg       svc;
    // bounded-response deadline countdown for the outstanding credits
    reg [3:0] timer;
    // budget still pooled for credits queued behind the one in service
    reg [3:0] rsv;

    initial begin
        credits = 3'd4;
        outst   = 3'd0;
        svc     = 1'b0;
        timer   = 4'd0;
        rsv     = 4'd0;
    end

    wire do_spend  = req && (credits != 3'd0) && (rsv <= 4'd6);
    wire do_return = (outst != 3'd0) && (svc == 1'b1);

    // outstanding count after this cycle's events
    wire [2:0] outst_nxt = outst + (do_spend  ? 3'd1 : 3'd0)
                                 - (do_return ? 3'd1 : 3'd0);
    // the working countdown is handed to the next queued credit when the
    // head credit finishes, and when the queue starts up from empty
    wire hand_off = (timer < 4'd2) && (outst_nxt != 3'd0);

    assign grant = i_ce && do_spend;
    assign busy  = (outst != 3'd0) || (rsv != 4'd0);

    always @(posedge clk) begin
        if (i_ce) begin
            if (rst) begin
                credits <= TOTAL;
                outst   <= 3'd0;
                svc     <= 1'b0;
                timer   <= 4'd0;
                rsv     <= 4'd0;
            end else begin
                // credit conservation: one token moves per event
                credits <= credits - (do_spend  ? 3'd1 : 3'd0)
                                   + (do_return ? 3'd1 : 3'd0);
                outst   <= outst   + (do_spend  ? 3'd1 : 3'd0)
                                   - (do_return ? 3'd1 : 3'd0);

                // two-cycle service phase per outstanding credit
                if (outst == 3'd0)
                    svc <= 1'b0;
                else
                    svc <= ~svc;

                // deadline budget: the head credit's 2 cycles are counted in
                // timer, every other credit's 2 cycles wait in the reserve
                timer <= timer - ((timer != 4'd0) ? 4'd1 : 4'd0)
                               + (hand_off ? 4'd2 : 4'd0);
                rsv   <= rsv   + (do_spend ? 4'd2 : 4'd0)
                               - (hand_off ? 4'd2 : 4'd0);
            end
        end
    end

    // Bounded response (safety): the countdown must never expire while a
    // credit is still outstanding at the consumer.
    always @(posedge clk)
        if (outst != 3'd0)
            assert (timer != 4'd0);

endmodule

